-- derrick-survey index schema v1 (DESIGN.md §9.B.8, D54/D55).
-- Owns .derrick/index.db, distinct from the substrate DB.

CREATE TABLE files (
    id            INTEGER PRIMARY KEY,
    path          TEXT NOT NULL UNIQUE,
    lang          TEXT NOT NULL,
    size          INTEGER NOT NULL,
    mtime         INTEGER NOT NULL,
    content_hash  TEXT NOT NULL
);

CREATE TABLE symbols (
    id          INTEGER PRIMARY KEY,
    file_id     INTEGER NOT NULL REFERENCES files(id) ON DELETE CASCADE,
    name        TEXT NOT NULL,
    kind        TEXT NOT NULL,
    start_line  INTEGER NOT NULL,
    end_line    INTEGER NOT NULL,
    signature   TEXT
);

-- A reference edge from one symbol to another. dst_symbol_id is nullable:
-- unresolved references (calls into std / extern crates / unindexed symbols)
-- keep their textual target in dst_name so impact queries still see them.
CREATE TABLE refs (
    src_symbol_id  INTEGER NOT NULL REFERENCES symbols(id) ON DELETE CASCADE,
    dst_symbol_id  INTEGER REFERENCES symbols(id) ON DELETE CASCADE,
    dst_name       TEXT NOT NULL,
    kind           TEXT NOT NULL
);

CREATE INDEX idx_symbols_name ON symbols(name);
CREATE INDEX idx_symbols_file ON symbols(file_id);
CREATE INDEX idx_refs_src ON refs(src_symbol_id);
CREATE INDEX idx_refs_dst ON refs(dst_symbol_id);
CREATE INDEX idx_refs_dst_name ON refs(dst_name);

-- External-content FTS5 over symbol name + signature. Kept in sync explicitly
-- by the writer (delete-by-file then re-insert), so no triggers are needed.
CREATE VIRTUAL TABLE symbols_fts USING fts5(
    name,
    signature,
    content = 'symbols',
    content_rowid = 'id'
);

PRAGMA user_version = 1;

//! `derrick-survey` — native code-graph index (DESIGN.md §9.B.8, D54/D55).
//!
//! A SQLite + FTS5 index of repository symbols, references, and call
//! relationships that AI agents query directly instead of fanning out across
//! `grep`/`glob`/`Read`. The index lives at `.derrick/index.db`, distinct from
//! the substrate DB, and is queried over an MCP server or the `derrick survey`
//! CLI subcommands.

use std::path::PathBuf;

/// Errors raised by the survey crate.
#[derive(Debug, thiserror::Error)]
pub enum SurveyError {
    /// A SQLite operation failed.
    #[error("sqlite error: {0}")]
    Sqlite(#[from] rusqlite::Error),
    /// An I/O operation failed.
    #[error("io error: {0}")]
    Io(#[from] std::io::Error),
    /// A worker task panicked or was cancelled.
    #[error("background task failed: {0}")]
    Join(#[from] tokio::task::JoinError),
    /// The on-disk schema is newer than this binary supports.
    #[error("index schema version {found} is newer than supported version {supported}")]
    SchemaTooNew {
        /// Version found on disk.
        found: u32,
        /// Highest version this binary understands.
        supported: u32,
    },
    /// An invariant was violated.
    #[error("{0}")]
    Internal(String),
}

/// Configuration for opening a [`Survey`] index.
#[derive(Clone, Debug)]
pub struct SurveyConfig {
    /// Path to the index SQLite file (conventionally `.derrick/index.db`).
    pub db_path: PathBuf,
    /// Repository root that the index covers.
    pub repo_root: PathBuf,
    /// Number of pooled read-only connections.
    pub reader_pool: usize,
}

impl SurveyConfig {
    /// Default reader-pool size, mirroring `derrick-substrate-native`.
    pub const DEFAULT_READER_POOL: usize = 4;
}

