/// A handle to an open survey index.
///
/// Holds the single writer connection behind a mutex and a pool of read-only
/// connections. All SQLite work runs inside `spawn_blocking`, since `rusqlite`
/// is synchronous.
#[derive(Clone)]
pub struct Survey {
    inner: std::sync::Arc<SurveyInner>,
}

struct SurveyInner {
    repo_root: PathBuf,
    writer: tokio::sync::Mutex<rusqlite::Connection>,
    readers: std::sync::Arc<db::ReaderPool>,
}

impl Survey {
    /// Open (creating and migrating if necessary) the index at the configured
    /// path. The parent directory must already exist.
    pub async fn open(config: SurveyConfig) -> Result<Self, SurveyError> {
        let SurveyConfig {
            db_path,
            repo_root,
            reader_pool,
        } = config;
        let inner = tokio::task::spawn_blocking(move || -> Result<SurveyInner, SurveyError> {
            let writer = db::open_writer_connection(&db_path)?;
            let readers = std::sync::Arc::new(db::ReaderPool::new(db_path, reader_pool)?);
            Ok(SurveyInner {
                repo_root,
                writer: tokio::sync::Mutex::new(writer),
                readers,
            })
        })
        .await??;
        Ok(Self {
            inner: std::sync::Arc::new(inner),
        })
    }

    /// Repository root this index covers.
    pub fn repo_root(&self) -> &std::path::Path {
        &self.inner.repo_root
    }
}

