 let refs: u64 = conn.query_row("SELECT COUNT(*) FROM refs", [], |r| r.get(0))?;
 let schema_version: u32 = conn.pragma_query_value(None, "user_version", |r| r.get(0))?;

 // Index state: path -> hash.
 let mut stmt = conn.prepare("SELECT path, content_hash FROM files")?;
 let mut indexed: std::collections::HashMap<String, String> = std::collections::HashMap::new();
 let rows = stmt.query_map([], |row| Ok((row.get::<_, String>(0)?, row.get::<_, String>(1)?)))?;
 for row in rows {
 let (path, hash) = row?;
 indexed.insert(path, hash);
 }

 let mut pending = Vec::new();
 let mut on_disk = HashSet::new();
 for file in walk::discover(repo_root) {
 on_disk.insert(file.rel_path.clone());
 let disk_hash = fs::read(&file.abs_path)
.ok()
.map(|bytes| blake3::hash(&bytes).to_hex().to_string());
 match (indexed.get(&file.rel_path), disk_hash) {
 (None, _) => pending.push(PendingFile {
 path: file.rel_path,
 reason: "new".to_owned(),
 }),
 (Some(prev), Some(now)) if *prev!= now => pending.push(PendingFile {
 path: file.rel_path,
 reason: "modified".to_owned(),
 }),
 _ => {}
 }
 }
 for path in indexed.keys() {
 if!on_disk.contains(path) {
 pending.push(PendingFile {
 path: path.clone(),
 reason: "deleted".to_owned(),
 });
 }
 }

 Ok(IndexStatus {
 files,
 symbols,
 refs,
 schema_version,
 pending,
 })
}
