//! MCP server exposing the survey index to coding agents (DESIGN.md §9.B.8).
//!
//! Four tools (`derrick_survey_search` / `_context` / `_impact` / `_status`)
//! over stdio. Freshness has three layers: (1) a debounced [`crate::watch`]
//! rebuild, (2) a per-response staleness banner emitted only while the index is
//! dirty, and (3) a connect-time incremental build before the first query.

use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::Arc;

use rmcp::handler::server::tool::ToolRouter;
use rmcp::handler::server::wrapper::Parameters;
use rmcp::model::{CallToolResult, Content, ServerCapabilities, ServerInfo};
use rmcp::service::ServiceExt;
use rmcp::transport::stdio;
use rmcp::{tool, tool_handler, tool_router, ErrorData as McpError, ServerHandler};
use schemars::JsonSchema;
use serde::Deserialize;

use crate::model::BuildOptions;
use crate::{Survey, SurveyError};

const DEFAULT_LIMIT: usize = 20;

#[derive(Debug, Deserialize, JsonSchema)]
struct QueryParams {
    /// Search terms (matched against symbol names and signatures).
    query: String,
    /// Maximum number of entry-point hits (default 20).
    #[serde(default)]
    limit: Option<usize>,
}

#[derive(Debug, Deserialize, JsonSchema)]
struct ImpactParams {
    /// Symbol name to resolve.
    symbol: String,
}

/// The MCP server state: a shared [`Survey`] plus the watcher's dirty flag.
#[derive(Clone)]
pub(crate) struct SurveyServer {
    survey: Survey,
    dirty: Arc<AtomicBool>,
    tool_router: ToolRouter<Self>,
}

#[tool_router]
impl SurveyServer {
    fn new(survey: Survey, dirty: Arc<AtomicBool>) -> Self {
        Self {
            survey,
            dirty,
            tool_router: Self::tool_router(),
        }
    }

    #[tool(description = "Full-text search over indexed symbol names and signatures. \
        Returns matching symbols with file:line locations.")]
    async fn derrick_survey_search(
        &self,
        params: Parameters<QueryParams>,
    ) -> Result<CallToolResult, McpError> {
        let limit = params.0.limit.unwrap_or(DEFAULT_LIMIT);
        let hits = self
            .survey
            .search(&params.0.query, limit)
            .await
            .map_err(internal)?;
        self.respond(&hits).await
    }

    #[tool(description = "Resolve a query to entry-point symbols plus the symbols \
        they reference — the one-call answer to an architecture question.")]
    async fn derrick_survey_context(
        &self,
        params: Parameters<QueryParams>,
    ) -> Result<CallToolResult, McpError> {
        let limit = params.0.limit.unwrap_or(DEFAULT_LIMIT);
        let context = self
            .survey
            .context(&params.0.query, limit)
            .await
            .map_err(internal)?;
        self.respond(&context).await
    }

    #[tool(description = "Show the direct callers and callees of a symbol — its \
        impact radius before you change it.")]
    async fn derrick_survey_impact(
        &self,
        params: Parameters<ImpactParams>,
    ) -> Result<CallToolResult, McpError> {
        let impact = self.survey.impact(&params.0.symbol).await.map_err(internal)?;
        self.respond(&impact).await
    }

    #[tool(description = "Index freshness and size summary, including files that \
        differ from the working tree.")]
    async fn derrick_survey_status(&self) -> Result<CallToolResult, McpError> {
        let status = self.survey.status().await.map_err(internal)?;
        self.respond(&status).await
    }

    /// Serialize a result to JSON, prefixing a staleness banner only when the
    /// watcher has flagged the index dirty (so the common path stays cheap).
    async fn respond<T: serde::Serialize>(&self, value: &T) -> Result<CallToolResult, McpError> {
        let mut contents = Vec::new();
        if self.dirty.load(Ordering::Relaxed) {
            if let Ok(status) = self.survey.status().await {
                if !status.pending.is_empty() {
                    let sample: Vec<&str> = status
                        .pending
                        .iter()
                        .take(10)
                        .map(|p| p.path.as_str())
                        .collect();
                    contents.push(Content::text(format!(
                        "STALE: {} file(s) differ from the index (e.g. {}). \
                         A rebuild is in progress; Read these files directly if you need current contents.",
                        status.pending.len(),
                        sample.join(", ")
                    )));
                }
            }
        }
        let json = serde_json::to_string_pretty(value)
            .map_err(|e| McpError::internal_error(e.to_string(), None))?;
        contents.push(Content::text(json));
        Ok(CallToolResult::success(contents))
    }
}

#[tool_handler]
impl ServerHandler for SurveyServer {
    fn get_info(&self) -> ServerInfo {
        ServerInfo {
            instructions: Some(
                "Query derrick's native code-graph index instead of fanning out across \
                 grep/glob/read. Use derrick_survey_search to find symbols, \
                 derrick_survey_context for architecture questions, derrick_survey_impact \
                 before changing a symbol, and derrick_survey_status to check freshness."
                    .to_owned(),
            ),
            capabilities: ServerCapabilities::builder().enable_tools().build(),
            ..Default::default()
        }
    }
}

fn internal(error: SurveyError) -> McpError {
    McpError::internal_error(error.to_string(), None)
}

/// Run the MCP server over stdio until the client disconnects.
///
/// Performs a connect-time incremental build (freshness layer 3), spawns the
/// debounced watcher (layer 1), then serves the four tools.
pub async fn serve_stdio(survey: Survey) -> Result<(), SurveyError> {
    // Layer 3: reconcile the index with the tree before answering anything.
    survey.build(BuildOptions::default()).await?;

    // Layer 1: background watcher keeps the index fresh and flips the dirty flag.
    let dirty = Arc::new(AtomicBool::new(false));
    tokio::spawn(watch_task(survey.clone(), Arc::clone(&dirty)));

    let server = SurveyServer::new(survey, dirty);
    let running = server
        .serve(stdio())
        .await
        .map_err(|e| SurveyError::Internal(format!("mcp serve failed: {e}")))?;
    running
        .waiting()
        .await
        .map_err(SurveyError::Join)
        .map(|_| ())
}

async fn watch_task(survey: Survey, dirty: Arc<AtomicBool>) {
    if let Err(error) = crate::watch::watch_loop(survey, dirty).await {
        tracing::warn!(%error, "survey watcher stopped");
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::{SurveyConfig, SurveyError};
    use rmcp::model::CallToolRequestParam;
    use rmcp::service::ServiceExt;

    async fn temp_survey() -> (tempfile::TempDir, Survey) {
        let tmp = tempfile::tempdir().unwrap();
        let repo = tmp.path();
        std::fs::write(
            repo.join("lib.rs"),
            "pub fn helper() {}\npub fn caller() {\n    helper();\n}\n",
        )
        .unwrap();
        std::fs::create_dir_all(repo.join(".derrick")).unwrap();
        let survey = Survey::open(SurveyConfig {
            db_path: repo.join(".derrick/index.db"),
            repo_root: repo.to_path_buf(),
            reader_pool: SurveyConfig::DEFAULT_READER_POOL,
        })
        .await
        .unwrap();
        survey.build(BuildOptions::default()).await.unwrap();
        (tmp, survey)
    }

    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn mcp_lists_and_calls_tools() -> Result<(), SurveyError> {
        let (_tmp, survey) = temp_survey().await;
        let (server_io, client_io) = tokio::io::duplex(8192);

        let server = SurveyServer::new(survey, Arc::new(AtomicBool::new(false)));
        let server_handle = tokio::spawn(async move {
            let running = server.serve(server_io).await.unwrap();
            let _ = running.waiting().await;
        });

        let client = rmcp::serve_client((), client_io).await.unwrap();

        let tools = client.list_all_tools().await.unwrap();
        let names: Vec<String> = tools.iter().map(|t| t.name.to_string()).collect();
        assert!(names.contains(&"derrick_survey_search".to_owned()));
        assert!(names.contains(&"derrick_survey_context".to_owned()));
        assert!(names.contains(&"derrick_survey_impact".to_owned()));
        assert!(names.contains(&"derrick_survey_status".to_owned()));

        let result = client
            .call_tool(CallToolRequestParam {
                name: "derrick_survey_search".into(),
                arguments: serde_json::json!({ "query": "helper", "limit": 5 })
                    .as_object()
                    .cloned(),
            })
            .await
            .unwrap();
        let body: String = result
            .content
            .iter()
            .filter_map(|c| c.as_text().map(|t| t.text.clone()))
            .collect();
        assert!(body.contains("helper"), "search result should mention helper: {body}");

        client.cancel().await.unwrap();
        server_handle.abort();
        Ok(())
    }
}

//! `derrick survey ...` subcommands: query the native code-graph index
//! (DESIGN.md §9.B.8, D54/D55).

use std::path::{Path, PathBuf};

use derrick_survey::{
    BuildOptions, BuildReport, ImpactSet, IndexStatus, Survey, SurveyConfig, SymbolContext,
    SymbolHit,
};

use crate::commands::{
    SurveyArgs, SurveyBuildArgs, SurveyCommand, SurveyImpactArgs, SurveyQueryArgs, SurveyServeArgs,
    SurveyStatusArgs,
};
use crate::exit_code::CliExitCode;
use crate::output::OutputFormat;
use crate::{create_dir_all, current_repo_root, message};

pub(crate) async fn execute(args: SurveyArgs) -> Result<CliExitCode, crate::CliError> {
    let repo_root = current_repo_root()?;
    let survey = open_survey(&repo_root).await?;
    match args.command {
        SurveyCommand::Build(build) => run_build(&survey, build).await,
        SurveyCommand::Search(query) => run_search(&survey, query).await,
        SurveyCommand::Context(query) => run_context(&survey, query).await,
        SurveyCommand::Impact(impact) => run_impact(&survey, impact).await,
        SurveyCommand::Status(status) => run_status(&survey, status).await,
        SurveyCommand::Serve(serve) => run_serve(survey, serve).await,
    }
}

async fn run_serve(survey: Survey, _args: SurveyServeArgs) -> Result<CliExitCode, crate::CliError> {
    derrick_survey::serve_stdio(survey)
        .await
        .map_err(|error| message(format!("survey serve: {error}")))?;
    Ok(CliExitCode::Success)
}

/// Index path: `.derrick/index.db`, distinct from the substrate DB (D11).
fn index_db_path(repo_root: &Path) -> PathBuf {
    repo_root.join(".derrick").join("index.db")
}

async fn open_survey(repo_root: &Path) -> Result<Survey, crate::CliError> {
    let db_path = index_db_path(repo_root);
    if let Some(parent) = db_path.parent() {
        create_dir_all(parent)?;
    }
    Survey::open(SurveyConfig {
        db_path,
        repo_root: repo_root.to_path_buf(),
        reader_pool: SurveyConfig::DEFAULT_READER_POOL,
    })
    .await
    .map_err(|error| message(format!("open survey index: {error}")))
}

async fn run_build(survey: &Survey, args: SurveyBuildArgs) -> Result<CliExitCode, crate::CliError> {
    let report = survey
        .build(BuildOptions { full: args.full })
        .await
        .map_err(|error| message(format!("survey build: {error}")))?;
    match args.format {
        OutputFormat::Json => print_json(&report)?,
        OutputFormat::Human => print_build_human(&report),
    }
    Ok(CliExitCode::Success)
}

async fn run_search(survey: &Survey, args: SurveyQueryArgs) -> Result<CliExitCode, crate::CliError> {
    let hits = survey
        .search(&args.query, args.limit)
        .await
        .map_err(|error| message(format!("survey search: {error}")))?;
    match args.format {
        OutputFormat::Json => print_json(&hits)?,
        OutputFormat::Human => {
            if hits.is_empty() {
                println!("No matches for {:?}.", args.query);
            } else {
                for hit in &hits {
                    print_hit(hit);
                }
            }
        }
    }
    Ok(CliExitCode::Success)
}

async fn run_context(
    survey: &Survey,
    args: SurveyQueryArgs,
) -> Result<CliExitCode, crate::CliError> {
    let context = survey
        .context(&args.query, args.limit)
        .await
        .map_err(|error| message(format!("survey context: {error}")))?;
    match args.format {
        OutputFormat::Json => print_json(&context)?,
        OutputFormat::Human => print_context_human(&context),
    }
    Ok(CliExitCode::Success)
}

async fn run_impact(
    survey: &Survey,
    args: SurveyImpactArgs,
) -> Result<CliExitCode, crate::CliError> {
    let impact = survey
        .impact(&args.symbol)
        .await
        .map_err(|error| message(format!("survey impact: {error}")))?;
    match args.format {
        OutputFormat::Json => print_json(&impact)?,
        OutputFormat::Human => match impact {
            None => println!("Symbol {:?} not found in the index.", args.symbol),
            Some(set) => print_impact_human(&set),
        },
    }
    Ok(CliExitCode::Success)
}

async fn run_status(
    survey: &Survey,
    args: SurveyStatusArgs,
) -> Result<CliExitCode, crate::CliError> {
    let status = survey
        .status()
        .await
        .map_err(|error| message(format!("survey status: {error}")))?;
    match args.format {
        OutputFormat::Json => print_json(&status)?,
        OutputFormat::Human => print_status_human(&status),
    }
    Ok(CliExitCode::Success)
}

fn print_json<T: serde::Serialize>(value: &T) -> Result<(), crate::CliError> {
    println!("{}", serde_json::to_string_pretty(value)?);
    Ok(())
}

fn print_hit(hit: &SymbolHit) {
    let sig = hit.signature.as_deref().unwrap_or("");
    println!(
        "{:<10} {}:{}-{}  {}  {}",
        hit.kind.as_str(),
        hit.path,
        hit.start_line,
        hit.end_line,
        hit.name,
        sig
    );
}

fn print_build_human(report: &BuildReport) {
    println!(
        "Indexed {} file(s), {} unchanged, {} removed.",
        report.files_indexed, report.files_unchanged, report.files_removed
    );
    println!("Index now holds {} symbols, {} references.", report.symbols, report.refs);
}

fn print_context_human(context: &SymbolContext) {
    println!("Entry points:");
    for hit in &context.entry_points {
        print_hit(hit);
    }
    if !context.related.is_empty() {
        println!("\nReferences:");
        for hit in &context.related {
            print_hit(hit);
        }
    }
}

fn print_impact_human(set: &ImpactSet) {
    println!("Symbol:");
    print_hit(&set.symbol);
    println!("\nCallers ({}):", set.callers.len());
    for hit in &set.callers {
        print_hit(hit);
    }
    println!("\nCallees ({}):", set.callees.len());
    for hit in &set.callees {
        print_hit(hit);
    }
}

fn print_status_human(status: &IndexStatus) {
    println!(
        "Index: {} files, {} symbols, {} refs (schema v{}).",
        status.files, status.symbols, status.refs, status.schema_version
    );
    if status.pending.is_empty() {
        println!("Up to date with the working tree.");
    } else {
        println!("{} file(s) differ from the index:", status.pending.len());
        for pending in &status.pending {
            println!("  {:<9} {}", pending.reason, pending.path);
        }
    }
}

//! Debounced filesystem watcher (freshness layer 1): on any change under the
//! repo root, mark the index dirty and trigger an incremental rebuild after a
//! short quiet period. The `dirty` flag lets the MCP layer surface a staleness
//! banner cheaply without re-hashing the tree on every query.

use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::Arc;
use std::time::Duration;

use notify::{RecursiveMode, Watcher};
use tokio::sync::mpsc;

use crate::model::BuildOptions;
use crate::{Survey, SurveyError};

const DEBOUNCE: Duration = Duration::from_millis(500);

/// Watch the repo and rebuild the index after each burst of changes. Runs
/// until the watcher channel closes. `dirty` is set when changes arrive and
/// cleared after a successful rebuild.
pub(crate) async fn watch_loop(survey: Survey, dirty: Arc<AtomicBool>) -> Result<(), SurveyError> {
    let (tx, mut rx) = mpsc::unbounded_channel();
    let mut watcher = notify::recommended_watcher(move |res: notify::Result<notify::Event>| {
        if res.is_ok() {
            let _ = tx.send(());
        }
    })?;
    watcher.watch(survey.repo_root(), RecursiveMode::Recursive)?;

    while rx.recv().await.is_some() {
        dirty.store(true, Ordering::Relaxed);
        // Drain the burst: keep resetting the timer until things go quiet.
        loop {
            tokio::select! {
                () = tokio::time::sleep(DEBOUNCE) => break,
                msg = rx.recv() => {
                    if msg.is_none() {
                        return Ok(());
                    }
                }
            }
        }
        if let Err(error) = survey.build(BuildOptions::default()).await {
            tracing::warn!(%error, "survey watch rebuild failed");
        } else {
            dirty.store(false, Ordering::Relaxed);
        }
    }
    Ok(())
}

//! Brownfield-safe init for existing repositories.
//!
//! The crate implements the T011 adoption phases from DESIGN.md §5.2, §5.6,
//! D29, and D34: detect existing project context, produce a deterministic
//! proposal, then apply the reviewed filesystem writes.

#![allow(clippy::pedantic)]

use std::collections::{BTreeMap, BTreeSet};
use std::ffi::OsStr;
use std::fs;
use std::io;
use std::path::{Path, PathBuf};
use std::time::Duration;

use chrono::Utc;
use derrick_config::{render_init_template, Config, InitTemplateVars, SubstrateMode};
use derrick_models::{resolve_role, AuthStore, CompletionRequest};
use derrick_substrate_native::{NativeConfig, NativeSubstrate};
use serde::{Deserialize, Serialize};
use serde_json::{json, Value};
use thiserror::Error;
use uuid::Uuid;

const INIT_TEMPLATE: &str = include_str!(concat!(
    env!("CARGO_MANIFEST_DIR"),
    "/../../templates/derrick.yaml.in"
));
const CONSTITUTION_STUB_TEMPLATE: &str = include_str!(concat!(
    env!("CARGO_MANIFEST_DIR"),
    "/../../templates/constitution.md.in"
