const CODEX_INSTRUCTIONS_TEMPLATE: &str = include_str!(concat!(
    env!("CARGO_MANIFEST_DIR"),
    "/../../templates/codex-instructions.md"
));
/// The `/speckit.constitution` Claude command shim. Written into target repos
