    if path.exists() {
        return Ok(false);
    }
    if let Some(parent) = path.parent() {
        fs::create_dir_all(parent).map_err(|source| AdoptError::Io {
            path: parent.to_path_buf(),
            source,
        })?;
    }
    fs::write(&path, CONSTITUTION_STUB_TEMPLATE)
        .map_err(|source| AdoptError::Io { path, source })?;
    Ok(true)
}

