impl DetectionReport {
 fn sort(&mut self) {
 self.claude_agents.sort();
 self.claude_commands.sort();
 self.claude_skills.sort();
 self.constitution_candidates.sort();
 self.tracker_prefixes.sort();
 self.tracker_prefixes.dedup();
 }
}

