1519	/// Remove the `<!-- derrick:start --> … <!-- derrick:end -->` block from `text`.
1520	fn strip_derrick_block(text: &str) -> String {
1521	    let Some(start) = text.find(DERRICK_BLOCK_START) else {
1522	        return text.to_owned();
1523	    };
1524	    let Some(end_relative) = text[start..].find(DERRICK_BLOCK_END) else {
1525	        return text.to_owned();
1526	    };
1527	    let end = start + end_relative + DERRICK_BLOCK_END.len();
1528	    // Trim one leading newline before the block and the trailing newline after.
1529	    let before = text[..start].trim_end_matches('\n');
1530	    let after = text[end..].trim_start_matches('\n');
1531	    if before.is_empty() && after.is_empty() {
1532	        String::new()
1533	    } else if before.is_empty() {
1534	        after.to_owned()
1535	    } else if after.is_empty() {
1536	        format!("{before}\n")
1537	    } else {
1538	        format!("{before}\n\n{after}")
1539	    }
1540	}
