1542	fn replace_or_append_block(existing: &str, block: &str) -> String {
1543	    if let Some(start) = existing.find(DERRICK_BLOCK_START) {
1544	        if let Some(end_relative) = existing[start..].find(DERRICK_BLOCK_END) {
1545	            let end = start + end_relative + DERRICK_BLOCK_END.len();
1546	            let mut rendered = String::new();
1547	            rendered.push_str(&existing[..start]);
1548	            rendered.push_str(block.trim_end());
1549	            rendered.push_str(&existing[end..]);
1550	            if !rendered.ends_with('\n') {
1551	                rendered.push('\n');
1552	            }
1553	            return rendered;
1554	        }
1555	    }
1556	
1557	    let mut rendered = existing.trim_end().to_owned();
1558	    if !rendered.is_empty() {
1559	        rendered.push_str("\n\n");
1560	    }
1561	    rendered.push_str(block.trim_end());
1562	    rendered.push('\n');
1563	    rendered
1564	}
