1566	fn tracker_prefixes(contents: &BTreeMap<PathBuf, String>) -> Vec<String> {
1567	    let mut prefixes = BTreeSet::new();
1568	    for content in contents.values() {
1569	        for token in
1570	            content.split(|character: char| !character.is_ascii_alphanumeric() && character != '-')
1571	        {
1572	            if let Some(prefix) = token.split_once('-').map(|(prefix, _)| prefix) {
1573	                if (2..=8).contains(&prefix.len())
1574	                    && prefix
1575	                        .chars()
1576	                        .all(|character| character.is_ascii_uppercase())
1577	                {
1578	                    prefixes.insert(format!("{prefix}-"));
1579	                }
1580	            }
1581	        }
1582	    }
1583	    prefixes.into_iter().collect()
1584	}
