 /// Source error.
 source: io::Error,
 },
 /// Invalid options.
 #[error("{0}")]
 InvalidOptions(String),
 /// Proposal has blockers.
 #[error("adoption blocked: {}",.0.join("; "))]
 Blocked(Vec<String>),
