 #[test]
 fn write_codex_instructions_creates_file() {
 let dir = tempdir().unwrap_or_else(|error| panic!("tempdir failed: {error}"));
 write_codex_instructions(dir.path())
.unwrap_or_else(|error| panic!("write failed: {error}"));
