}

fn scrub_with_rules(rules: Option<&RuleSet>, input: &[u8]) -> (Vec<u8>, ScrubStats) {
 let mut engine = Engine::new(rules);
 for line in split_lines(input) {
 engine.process_line(&line);
 }
