1	//! End-to-end build + query test over a small mixed-language fixture repo.
2	
3	use std::fs;
4	
5	use derrick_survey::{BuildOptions, Survey, SurveyConfig};
6	
7	async fn open_index(repo: &std::path::Path) -> Survey {
8	    let derrick_dir = repo.join(".derrick");
9	    fs::create_dir_all(&derrick_dir).unwrap();
10	    Survey::open(SurveyConfig {
11	        db_path: derrick_dir.join("index.db"),
12	        repo_root: repo.to_path_buf(),
13	        reader_pool: SurveyConfig::DEFAULT_READER_POOL,
14	    })
15	    .await
16	    .unwrap()
17	}
18	
19	#[tokio::test]
20	async fn builds_and_queries_a_mixed_repo() {
21	    let tmp = tempfile::tempdir().unwrap();
22	    let repo = tmp.path();
23	
24	    fs::write(
25	        repo.join("lib.rs"),
26	        "pub fn helper() {}\npub fn caller() {\n    helper();\n}\n",
27	    )
28	    .unwrap();
29	    fs::write(
30	        repo.join("app.py"),
31	        "def worker():\n    helper()\n\ndef helper():\n    pass\n",
32	    )
33	    .unwrap();
34	    fs::write(
35	        repo.join("svc.go"),
36	        "package main\ntype Server struct{}\nfunc serve() {\n\tlisten()\n}\nfunc listen() {}\n",
37	    )
38	    .unwrap();
39	    fs::write(
40	        repo.join("widget.ts"),
41	        "interface Props { id: number }\nclass Widget {\n  render() { draw(); }\n}\nfunction draw() {}\n",
42	    )
43	    .unwrap();
44	    fs::write(
45	        repo.join("util.js"),
46	        "const compute = (a, b) => a + b;\nfunction main() {\n  compute(1, 2);\n}\n",
47	    )
48	    .unwrap();
49	    // A directory that must be pruned.
50	    fs::create_dir_all(repo.join("node_modules")).unwrap();
51	    fs::write(repo.join("node_modules/skip.js"), "function ignored() {}\n").unwrap();
52	
53	    let survey = open_index(repo).await;
54	
55	    let report = survey.build(BuildOptions::default()).await.unwrap();
56	    assert_eq!(
57	        report.files_indexed, 5,
58	        "five source files, node_modules pruned"
59	    );
60	    assert!(report.symbols >= 4);
61	
62	    // Search finds the Rust helper.
63	    let hits = survey.search("helper", 10).await.unwrap();
64	    assert!(hits.iter().any(|h| h.name == "helper"));
65	
66	    // Every target language reaches the index through the build pipeline.
67	    for (query, symbol) in [
68	        ("serve", "serve"),     // Go
69	        ("Widget", "Widget"),   // TypeScript
70	        ("compute", "compute"), // JavaScript
71	    ] {
72	        let hits = survey.search(query, 10).await.unwrap();
73	        assert!(
74	            hits.iter().any(|h| h.name == symbol),
75	            "expected to find {symbol} from the {query} fixture"
76	        );
77	    }
78	
79	    // Cross-language impact within a single language still resolves (Go).
80	    let go_impact = survey
81	        .impact("listen")
82	        .await
83	        .unwrap()
84	        .expect("listen exists");
85	    assert!(go_impact.callers.iter().any(|h| h.name == "serve"));
86	
87	    // Impact: helper is called by caller (Rust) and worker (Python) by name.
88	    let impact = survey
89	        .impact("helper")
90	        .await
91	        .unwrap()
92	        .expect("helper exists");
93	    let caller_names: Vec<&str> = impact.callers.iter().map(|h| h.name.as_str()).collect();
94	    assert!(caller_names.contains(&"caller"));
95	    assert!(caller_names.contains(&"worker"));
96	
97	    // Context for caller includes helper among related symbols.
98	    let ctx = survey.context("caller", 5).await.unwrap();
99	    assert!(ctx.entry_points.iter().any(|h| h.name == "caller"));
100	    assert!(ctx.related.iter().any(|h| h.name == "helper"));
101	
102	    // Status: clean immediately after a full build.
103	    let status = survey.status().await.unwrap();
104	    assert_eq!(status.files, 5);
105	    assert!(status.pending.is_empty(), "no pending files after build");
106	
107	    // Incremental: edit a file, status reports it modified, rebuild picks it up.
108	    fs::write(
109	        repo.join("app.py"),
110	        "def worker():\n    helper()\n\ndef helper():\n    pass\n\ndef extra():\n    pass\n",
111	    )
112	    .unwrap();
113	    let status = survey.status().await.unwrap();
114	    assert!(status
115	        .pending
116	        .iter()
117	        .any(|p| p.path == "app.py" && p.reason == "modified"));
118	
119	    let report = survey.build(BuildOptions::default()).await.unwrap();
120	    assert_eq!(report.files_indexed, 1, "only the changed file reparsed");
121	    assert_eq!(report.files_unchanged, 4);
122	    let hits = survey.search("extra", 10).await.unwrap();
123	    assert!(hits.iter().any(|h| h.name == "extra"));
124	}

