1	//! SQLite connection management for the survey index.
2	//!
3	//! Mirrors `derrick-substrate-native`'s single-writer + reader-pool pattern,
4	//! but opens the database in WAL journal mode: the survey index is read-heavy
5	//! with many concurrent worktree readers (D38) and an infrequent writer, so WAL
6	//! lets readers proceed without blocking the build (rust-architect sign-off).
7	
8	use std::path::{Path, PathBuf};
9	use std::sync::{Arc, Mutex};
10	
11	use rusqlite::{Connection, OpenFlags};
12	
13	use crate::SurveyError;
14	
15	/// Highest schema version this binary understands.
16	pub(crate) const SCHEMA_VERSION: u32 = 1;
17	
18	const MIGRATION_0001: &str = include_str!("../migrations/0001_initial.sql");
19	
20	/// A pool of read-only connections handed out under lease.
21	pub(crate) struct ReaderPool {
22	    db_path: PathBuf,
23	    max_size: usize,
24	    connections: Mutex<Vec<Connection>>,
25	}
26	
27	impl ReaderPool {
28	    pub(crate) fn new(db_path: PathBuf, size: usize) -> Result<Self, SurveyError> {
29	        let mut connections = Vec::with_capacity(size);
30	        for _ in 0..size {
31	            connections.push(open_reader_connection(&db_path)?);
32	        }
33	        Ok(Self {
34	            db_path,
35	            max_size: size,
36	            connections: Mutex::new(connections),
37	        })
38	    }
39	
40	    pub(crate) fn lease(self: &Arc<Self>) -> Result<ReaderLease, SurveyError> {
41	        let connection = {
42	            let mut connections = self
43	                .connections
44	                .lock()
45	                .map_err(|_| SurveyError::Internal("reader pool mutex poisoned".to_owned()))?;
46	            connections.pop()
47	        };
48	        Ok(ReaderLease {
49	            connection: Some(match connection {
50	                Some(connection) => connection,
