 options.full || existing.get(&m.rel_path).is_none_or(|prev| prev!= &m.hash)
 });

 // Phase 3: parse changed files in parallel.
 let parsed: Vec<(&FileMeta, ParsedFile)> = changed
.par_iter()
.map(|m| parse::parse(m.lang, &m.content).map(|p| (*m, p)))
.collect::<Result<_, _>>()?;

