}

/// Result of an `impact` query: who depends on a symbol.
#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct ImpactSet {
 /// The symbol the query resolved to.
 pub symbol: SymbolHit,
 /// Direct callers / referrers of the symbol.
