212	async fn brownfield_init(
213	    repo_root: &Path,
214	    resolved: &ResolvedInitOptions,
215	) -> Result<CliExitCode, crate::CliError> {
216	    let adopter = Adopter::new(repo_root);
217	    let detection = adopter.detect()?;
218	    let opts = AdoptOptions {
219	        site_name: resolved.site_name.clone(),
220	        site_prefix: resolved.prefix.clone(),
221	        mode: init_mode_to_substrate(resolved.mode),
222	        force: resolved.force,
223	        no_hooks: resolved.no_hooks,
224	        append_agents_md: resolved.append_agents_md,
225	        constitution: resolved.constitution,
226	    };
227	    let drafted_constitution = if opts.constitution == ConstitutionMode::FromDocs {
228	        Some(adopter.draft_constitution(&detection, &opts).await?)
229	    } else {
230	        None
231	    };
232	    let mut plan = adopter.propose(&detection, &opts, drafted_constitution.as_deref())?;
233	    override_plan_yaml(&mut plan, resolved)?;
234	    print_plan(&plan);
235	    if !plan.blockers.is_empty() {
236	        return Ok(CliExitCode::Failure);
237	    }
238	    if resolved.dry_run {
239	        return Ok(CliExitCode::Success);
240	    }
241	
242	    let outcome = adopter.apply(&plan).await?;
243	    println!();
244	    if is_styled() {
245	        println!(
246	            "  \x1b[32m✓\x1b[0m  \x1b[1m{}\x1b[0m  ready",
247	            opts.site_name
248	        );
249	    } else {
250	        println!("  ✓  {}  ready", opts.site_name);
251	    }
252	    println!();
253	    for path in &outcome.written {
254	        print_written(&path.display().to_string());
255	    }
256	    if !outcome.bookkeeping.is_empty() {
257	        for path in &outcome.bookkeeping {
258	            print_written(&path.display().to_string());
259	        }
260	    }
261	    if resolved.vscode {
262	        write_vscode_configs(repo_root)?;
263	    }
264	    if resolved.jetbrains {
265	        write_jetbrains_configs(repo_root)?;
266	    }
267	    if !resolved.yes {
268	        println!();
269	        if is_styled() {
270	            println!("  \x1b[36m›\x1b[0m  review `git status` before committing");
271	        } else {
272	            println!("  ›  review `git status` before committing");
273	        }
274	    }
275	    println!();
276	    Ok(CliExitCode::Success)
277	}
