279	async fn greenfield_init(
280	    repo_root: &Path,
281	    resolved: &ResolvedInitOptions,
282	) -> Result<CliExitCode, crate::CliError> {
283	    let config_path = repo_root.join("derrick.yaml");
284	    if config_path.exists() && !resolved.force {
285	        return Err(message(format!(
286	            "{} already exists; rerun with --force to overwrite it",
287	            config_path.display()
288	        )));
289	    }
290	
291	    let rendered = render_init_template(
292	        INIT_TEMPLATE,
293	        InitTemplateVars {
294	            site_name: &resolved.site_name,
295	            prefix: &resolved.prefix,
296	            mode: resolved.mode.as_str(),
297	        },
298	    );
299	    let rendered = apply_config_overrides(&rendered, resolved)?;
300	    write_file(&config_path, &rendered)?;
301	
302	    let config = read_config(repo_root)?;
303	    create_dir_all(&repo_root.join(config.state().dir()))?;
304	    let gitignore = repo_root.join(config.state().dir()).join(".gitignore");
305	    write_file(&gitignore, "runs/\nstate.json\nindex.db*\nworktrees/\n")?;
306	
307	    let substrate =
308	        NativeSubstrate::open(native_paths(repo_root, &config), config.site().clone()).await?;
309	    substrate.close().await?;
310	
311	    if !resolved.no_hooks {
312	        derrick_adopt::write_codex_instructions(repo_root).map_err(|e| message(e.to_string()))?;
313	        derrick_adopt::write_claude_settings(repo_root, resolved.force)
314	            .map_err(|e| message(e.to_string()))?;
315	        if which::which("specify").is_err() {
316	            ensure_speckit(resolved.yes)?;
317	        }
318	        let written_commands = derrick_adopt::write_claude_commands(repo_root, resolved.force)
319	            .map_err(|e| message(e.to_string()))?;
320	        print_written(".codex/instructions.md");
321	        print_written(".claude/settings.json");
322	        for path in &written_commands {
323	            print_written(path);
324	        }
325	    }
326	
327	    // Register the survey MCP server regardless of --no-hooks; the server
328	    // declaration is independent of the D29 hook config (D54/D57).
329	    derrick_adopt::write_mcp_json(repo_root).map_err(|e| message(e.to_string()))?;
330	    print_written(".mcp.json");
331	
332	    if resolved.vscode {
333	        write_vscode_configs(repo_root)?;
334	    }
335	    if resolved.jetbrains {
336	        write_jetbrains_configs(repo_root)?;
337	    }
338	
339	    // Seed the constitution so assay is never silently skipped on the first run.
340	    // This call overwrites any unedited speckit placeholder written above.
341	    seed_constitution(repo_root, &config, resolved.yes)?;
342	
343	    // Make an initial commit so `git worktree add ... HEAD` succeeds on the
344	    // first `derrick add`. Only runs when the repo has no commits yet.
345	    maybe_initial_commit(repo_root)?;
346	
347	    print_summary(&config, resolved.ai_style);
348	    Ok(CliExitCode::Success)
349	}
