365	fn apply_text_overrides(rendered: &str, resolved: &ResolvedInitOptions) -> String {
366	    let mut lines = rendered
367	        .lines()
368	        .map(std::borrow::ToOwned::to_owned)
369	        .collect::<Vec<_>>();
370	
371	    if let Some(mode_index) = lines
372	        .iter()
373	        .position(|line| line.trim_start().starts_with("mode: "))
374	    {
375	        let indent = lines[mode_index]
376	            .chars()
377	            .take_while(|ch| ch.is_whitespace())
378	            .collect::<String>();
379	        lines[mode_index] = format!("{indent}mode: {}", resolved.mode.as_str());
380	    }
381	
382	    if let Some(roles_start) = lines.iter().position(|line| line == "roles:") {
383	        let mut roles_end = roles_start + 1;
384	        while roles_end < lines.len() {
385	            let line = &lines[roles_end];
386	            if line.is_empty() || line.starts_with("  ") {
387	                roles_end += 1;
388	            } else {
389	                break;
390	            }
391	        }
392	        let replacement = vec![
393	            "roles:".to_owned(),
394	            format!("  proposer: {}", resolved.roles.proposer),
395	            format!("  drafter: {}", resolved.roles.drafter),
396	            format!("  reviewer: {}", resolved.roles.reviewer),
397	            format!("  executor: {}", resolved.roles.executor),
398	            format!("  summariser: {}", resolved.roles.summariser),
399	        ];
400	        lines.splice(roles_start..roles_end, replacement);
401	    }
402	
403	    if matches!(resolved.mode, crate::commands::InitMode::Crew)
404	        && !lines.iter().any(|line| line.trim() == "- id: bridge")
405	    {
406	        if let Some(guardrails_index) = lines.iter().position(|line| line == "guardrails:") {
407	            let addition = vec![
408	                "  - id: bridge".to_owned(),
409	                "    runner: derrick".to_owned(),
410	                "  - id: foreman".to_owned(),
411	                "    runner: derrick".to_owned(),
412	                "    executor_role: executor".to_owned(),
413	            ];
414	            lines.splice(guardrails_index..guardrails_index, addition);
415	        }
416	    }
417	
418	    format!("{}\n", lines.join("\n"))
419	}
