421	fn apply_config_overrides(
422	    rendered: &str,
423	    resolved: &ResolvedInitOptions,
424	) -> Result<String, crate::CliError> {
425	    let mut yaml: serde_yaml::Value =
426	        serde_yaml::from_str(rendered).map_err(|error| message(error.to_string()))?;
427	    let root = yaml
428	        .as_mapping_mut()
429	        .ok_or_else(|| message("rendered config is not a mapping"))?;
430	
431	    let tools = nested_mapping(root, "tools")?;
432	    let substrate = nested_mapping(tools, "substrate")?;
433	    substrate.insert(
434	        serde_yaml::Value::String("mode".to_owned()),
435	        serde_yaml::Value::String(resolved.mode.as_str().to_owned()),
436	    );
437	
438	    let roles = role_mapping_value(&resolved.roles);
439	    root.insert(
440	        serde_yaml::Value::String("roles".to_owned()),
441	        serde_yaml::Value::Mapping(roles),
442	    );
443	
444	    if matches!(resolved.mode, crate::commands::InitMode::Crew) {
445	        ensure_crew_pipeline(root)?;
446	    }
447	
448	    serde_yaml::to_string(&yaml).map_err(|error| message(error.to_string()))
449	}
450	
451	pub(crate) fn nested_mapping<'a>(
452	    mapping: &'a mut serde_yaml::Mapping,
453	    key: &str,
454	) -> Result<&'a mut serde_yaml::Mapping, crate::CliError> {
455	    let key_value = serde_yaml::Value::String(key.to_owned());
456	    if !mapping.contains_key(&key_value) {
457	        mapping.insert(
458	            key_value.clone(),
459	            serde_yaml::Value::Mapping(serde_yaml::Mapping::new()),
460	        );
461	    }
462	    mapping
463	        .get_mut(&key_value)
464	        .and_then(serde_yaml::Value::as_mapping_mut)
465	        .ok_or_else(|| message(format!("{key} is not a mapping")))
466	}
467	
468	fn role_mapping_value(roles: &RoleBindings) -> serde_yaml::Mapping {
469	    let mut mapping = serde_yaml::Mapping::new();
470	    for (role, model) in roles.entries() {
471	        mapping.insert(
472	            serde_yaml::Value::String(role.to_owned()),
473	            serde_yaml::Value::String(model.to_owned()),
474	        );
475	    }
476	    mapping
477	}
