479	pub(crate) fn ensure_crew_pipeline(root: &mut serde_yaml::Mapping) -> Result<(), crate::CliError> {
480	    let key = serde_yaml::Value::String("pipeline".to_owned());
481	    let pipeline_value = root
482	        .get_mut(&key)
483	        .ok_or_else(|| message("pipeline is missing from rendered config"))?;
484	    let steps = pipeline_value
485	        .as_sequence_mut()
486	        .ok_or_else(|| message("pipeline is not a sequence"))?;
487	
488	    let has_bridge = steps.iter().any(|step| step_id(step) == Some("bridge"));
489	    if !has_bridge {
490	        steps.push(yaml_step(&[("id", "bridge"), ("runner", "derrick")]));
491	    }
492	
493	    let has_foreman = steps.iter().any(|step| step_id(step) == Some("foreman"));
494	    if !has_foreman {
495	        let mut step = yaml_step(&[("id", "foreman"), ("runner", "derrick")]);
496	        if let Some(mapping) = step.as_mapping_mut() {
497	            mapping.insert(
498	                serde_yaml::Value::String("executor_role".to_owned()),
499	                serde_yaml::Value::String("executor".to_owned()),
500	            );
501	        }
502	        steps.push(step);
503	    }
504	
505	    Ok(())
506	}
507	
508	pub(crate) fn yaml_step(entries: &[(&str, &str)]) -> serde_yaml::Value {
509	    let mut step = serde_yaml::Mapping::new();
510	    for (key, value) in entries {
511	        step.insert(
512	            serde_yaml::Value::String((*key).to_owned()),
513	            serde_yaml::Value::String((*value).to_owned()),
514	        );
515	    }
516	    serde_yaml::Value::Mapping(step)
517	}
518	
519	pub(crate) fn step_id(step: &serde_yaml::Value) -> Option<&str> {
520	    let id_key = serde_yaml::Value::String("id".to_owned());
521	    step.as_mapping()?.get(&id_key)?.as_str()
522	}
