734	fn ensure_git_repo(yes: bool) -> Result<std::path::PathBuf, crate::CliError> {
735	    let cwd = std::env::current_dir().map_err(|source| crate::CliError::Io {
736	        path: std::path::PathBuf::from("."),
737	        source,
738	    })?;
739	
740	    if is_styled() {
741	        eprintln!("  \x1b[33m⚠\x1b[0m  No git repository found in this directory or any parent.");
742	    } else {
743	        eprintln!("  ⚠  No git repository found in this directory or any parent.");
744	    }
745	
746	    let confirmed = if yes {
747	        true
748	    } else if std::io::stdin().is_terminal() {
749	        if is_styled() {
750	            eprint!(
751	                "  \x1b[36m›\x1b[0m  Run \x1b[1mgit init\x1b[0m in {}? [Y/n] ",
752	                cwd.display()
753	            );
754	        } else {
755	            eprint!("  ›  Run `git init` in {}? [Y/n] ", cwd.display());
756	        }
757	        use std::io::Write as _;
