 });
 }
 };

 if!status.success() {
 if is_styled() {
 eprintln!(" \x1b[33m⚠\x1b[0m speckit install failed — falling back to shims.");
 eprintln!(" Run \x1b[1muv tool install specify-cli\x1b[0m manually and re-run \x1b[1mderrick init\x1b[0m.");
 } else {
