//! End-to-end build + query test over a small mixed-language fixture repo.

use std::fs;

use derrick_survey::{BuildOptions, Survey, SurveyConfig};

async fn open_index(repo: &std::path::Path) -> Survey {
    let derrick_dir = repo.join(".derrick");
    fs::create_dir_all(&derrick_dir).unwrap();
    Survey::open(SurveyConfig {
        db_path: derrick_dir.join("index.db"),
        repo_root: repo.to_path_buf(),
        reader_pool: SurveyConfig::DEFAULT_READER_POOL,
    })
    .await
    .unwrap()
}

#[tokio::test]
async fn builds_and_queries_a_mixed_repo() {
    let tmp = tempfile::tempdir().unwrap();
    let repo = tmp.path();

    fs::write(
        repo.join("lib.rs"),
        "pub fn helper() {}\npub fn caller() {\n    helper();\n}\n",
    )
    .unwrap();
    fs::write(
        repo.join("app.py"),
        "def worker():\n    helper()\n\ndef helper():\n    pass\n",
    )
    .unwrap();
    fs::write(
        repo.join("svc.go"),
        "package main\ntype Server struct{}\nfunc serve() {\n\tlisten()\n}\nfunc listen() {}\n",
    )
    .unwrap();
    fs::write(
        repo.join("widget.ts"),
        "interface Props { id: number }\nclass Widget {\n  render() { draw(); }\n}\nfunction draw() {}\n",
    )
    .unwrap();
    fs::write(
        repo.join("util.js"),
        "const compute = (a, b) => a + b;\nfunction main() {\n  compute(1, 2);\n}\n",
    )
    .unwrap();
    // A directory that must be pruned.
    fs::create_dir_all(repo.join("node_modules")).unwrap();
    fs::write(repo.join("node_modules/skip.js"), "function ignored() {}\n").unwrap();

    let survey = open_index(repo).await;

    let report = survey.build(BuildOptions::default()).await.unwrap();
    assert_eq!(
        report.files_indexed, 5,
        "five source files, node_modules pruned"
    );
    assert!(report.symbols >= 4);

    // Search finds the Rust helper.
    let hits = survey.search("helper", 10).await.unwrap();
    assert!(hits.iter().any(|h| h.name == "helper"));

    // Every target language reaches the index through the build pipeline.
    for (query, symbol) in [
        ("serve", "serve"),     // Go
        ("Widget", "Widget"),   // TypeScript
        ("compute", "compute"), // JavaScript
    ] {
        let hits = survey.search(query, 10).await.unwrap();
        assert!(
            hits.iter().any(|h| h.name == symbol),
            "expected to find {symbol} from the {query} fixture"
        );
    }

    // Cross-language impact within a single language still resolves (Go).
    let go_impact = survey
        .impact("listen")
        .await
        .unwrap()
        .expect("listen exists");
    assert!(go_impact.callers.iter().any(|h| h.name == "serve"));

    // Impact: helper is called by caller (Rust) and worker (Python) by name.
    let impact = survey
        .impact("helper")
        .await
        .unwrap()
        .expect("helper exists");
    let caller_names: Vec<&str> = impact.callers.iter().map(|h| h.name.as_str()).collect();
    assert!(caller_names.contains(&"caller"));
    assert!(caller_names.contains(&"worker"));

    // Context for caller includes helper among related symbols.
    let ctx = survey.context("caller", 5).await.unwrap();
    assert!(ctx.entry_points.iter().any(|h| h.name == "caller"));
    assert!(ctx.related.iter().any(|h| h.name == "helper"));

    // Status: clean immediately after a full build.
    let status = survey.status().await.unwrap();
    assert_eq!(status.files, 5);
    assert!(status.pending.is_empty(), "no pending files after build");

    // Incremental: edit a file, status reports it modified, rebuild picks it up.
    fs::write(
        repo.join("app.py"),
        "def worker():\n    helper()\n\ndef helper():\n    pass\n\ndef extra():\n    pass\n",
    )
    .unwrap();
    let status = survey.status().await.unwrap();
    assert!(status
        .pending
        .iter()
        .any(|p| p.path == "app.py" && p.reason == "modified"));

    let report = survey.build(BuildOptions::default()).await.unwrap();
    assert_eq!(report.files_indexed, 1, "only the changed file reparsed");
    assert_eq!(report.files_unchanged, 4);
    let hits = survey.search("extra", 10).await.unwrap();
    assert!(hits.iter().any(|h| h.name == "extra"));
}

//! Read-side queries: full-text search, context, impact, and status. All take
//! a borrowed read-only [`Connection`] and run inside `spawn_blocking`.

use std::collections::HashSet;
use std::fs;
use std::path::Path;

use rusqlite::{params, Connection, Row};

use crate::model::{ImpactSet, IndexStatus, PendingFile, SymbolContext, SymbolHit, SymbolKind};
use crate::walk;
use crate::SurveyError;

/// Columns selected for a [`SymbolHit`], plus the symbol id as column 0.
const HIT_COLUMNS: &str = "s.id, s.name, s.kind, f.path, s.start_line, s.end_line, s.signature";

fn row_to_hit(row: &Row) -> rusqlite::Result<(i64, SymbolHit)> {
    let id: i64 = row.get(0)?;
    let kind: String = row.get(2)?;
    Ok((
        id,
        SymbolHit {
            name: row.get(1)?,
            kind: SymbolKind::from_wire(&kind),
            path: row.get(3)?,
            start_line: row.get(4)?,
            end_line: row.get(5)?,
            signature: row.get(6)?,
        },
    ))
}

/// Build an FTS5 MATCH expression: each whitespace token becomes a quoted
/// prefix term, AND-ed together. Quoting neutralises FTS5 syntax in user input.
fn fts_query(raw: &str) -> String {
    raw.split_whitespace()
        .map(|t| format!("\"{}\"*", t.replace('"', "\"\"")))
        .collect::<Vec<_>>()
        .join(" ")
}

/// Full-text search returning symbol ids paired with hits, ranked by FTS5.
fn search_rows(
    conn: &Connection,
    query: &str,
    limit: usize,
) -> Result<Vec<(i64, SymbolHit)>, SurveyError> {
    let match_expr = fts_query(query);
    if match_expr.is_empty() {
        return Ok(Vec::new());
    }
    let sql = format!(
        "SELECT {HIT_COLUMNS}
         FROM symbols_fts fts
         JOIN symbols s ON s.id = fts.rowid
         JOIN files f ON f.id = s.file_id
         WHERE symbols_fts MATCH ?1
         ORDER BY rank
         LIMIT ?2"
    );
    let mut stmt = conn.prepare(&sql)?;
    let rows = stmt.query_map(params![match_expr, limit as i64], row_to_hit)?;
    let mut out = Vec::new();
    for row in rows {
        out.push(row?);
    }
    Ok(out)
}

/// Public search: hits only.
pub(crate) fn search(
    conn: &Connection,
    query: &str,
    limit: usize,
) -> Result<Vec<SymbolHit>, SurveyError> {
    Ok(search_rows(conn, query, limit)?
        .into_iter()
        .map(|(_, hit)| hit)
        .collect())
}

/// Context: entry-point symbols plus the resolved symbols they reference.
pub(crate) fn context(
    conn: &Connection,
    query: &str,
    limit: usize,
) -> Result<SymbolContext, SurveyError> {
    let entries = search_rows(conn, query, limit)?;
    let mut related = Vec::new();
    let mut seen: HashSet<i64> = entries.iter().map(|(id, _)| *id).collect();

    let sql = format!(
        "SELECT DISTINCT {HIT_COLUMNS}
         FROM refs r
         JOIN symbols s ON s.id = r.dst_symbol_id
         JOIN files f ON f.id = s.file_id
         WHERE r.src_symbol_id = ?1 AND r.dst_symbol_id IS NOT NULL"
    );
    let mut stmt = conn.prepare(&sql)?;
    for (id, _) in &entries {
        let rows = stmt.query_map(params![id], row_to_hit)?;
        for row in rows {
            let (rid, hit) = row?;
            if seen.insert(rid) {
                related.push(hit);
            }
        }
    }

    Ok(SymbolContext {
        entry_points: entries.into_iter().map(|(_, hit)| hit).collect(),
        related,
    })
}

/// Impact: the resolved symbol with its direct callers and callees.
pub(crate) fn impact(conn: &Connection, symbol: &str) -> Result<Option<ImpactSet>, SurveyError> {
    let select = format!(
        "SELECT {HIT_COLUMNS} FROM symbols s JOIN files f ON f.id = s.file_id
         WHERE s.name = ?1 LIMIT 1"
    );
    let mut stmt = conn.prepare(&select)?;
    let Some((symbol_id, symbol_hit)) = stmt.query_row(params![symbol], row_to_hit).ok() else {
        return Ok(None);
    };

    // Callers: any edge whose textual target is this symbol's name.
    let callers_sql = format!(
        "SELECT DISTINCT {HIT_COLUMNS}
         FROM refs r
         JOIN symbols s ON s.id = r.src_symbol_id
         JOIN files f ON f.id = s.file_id
         WHERE r.dst_name = ?1"
    );
    let mut stmt = conn.prepare(&callers_sql)?;
    let callers = collect_hits(stmt.query_map(params![symbol_hit.name], row_to_hit)?)?;

    // Callees: resolved outgoing edges from this symbol.
    let callees_sql = format!(
        "SELECT DISTINCT {HIT_COLUMNS}
         FROM refs r
         JOIN symbols s ON s.id = r.dst_symbol_id
         JOIN files f ON f.id = s.file_id
         WHERE r.src_symbol_id = ?1 AND r.dst_symbol_id IS NOT NULL"
    );
    let mut stmt = conn.prepare(&callees_sql)?;
    let callees = collect_hits(stmt.query_map(params![symbol_id], row_to_hit)?)?;

    Ok(Some(ImpactSet {
        symbol: symbol_hit,
        callers,
        callees,
    }))
}

fn collect_hits(
    rows: impl Iterator<Item = rusqlite::Result<(i64, SymbolHit)>>,
) -> Result<Vec<SymbolHit>, SurveyError> {
    let mut out = Vec::new();
    for row in rows {
        out.push(row?.1);
    }
    Ok(out)
}

/// Status: counts plus the set of files that differ from the working tree.
pub(crate) fn status(conn: &Connection, repo_root: &Path) -> Result<IndexStatus, SurveyError> {
    let files: i64 = conn.query_row("SELECT COUNT(*) FROM files", [], |r| r.get(0))?;
    let symbols: i64 = conn.query_row("SELECT COUNT(*) FROM symbols", [], |r| r.get(0))?;
    let refs: i64 = conn.query_row("SELECT COUNT(*) FROM refs", [], |r| r.get(0))?;
    let schema_version: u32 = conn.pragma_query_value(None, "user_version", |r| r.get(0))?;

    // Index state: path -> hash.
    let mut stmt = conn.prepare("SELECT path, content_hash FROM files")?;
    let mut indexed: std::collections::HashMap<String, String> = std::collections::HashMap::new();
    let rows = stmt.query_map([], |row| {
        Ok((row.get::<_, String>(0)?, row.get::<_, String>(1)?))
    })?;
    for row in rows {
        let (path, hash) = row?;
        indexed.insert(path, hash);
    }

    let mut pending = Vec::new();
    let mut on_disk = HashSet::new();
    for file in walk::discover(repo_root) {
        on_disk.insert(file.rel_path.clone());
        let disk_hash = fs::read(&file.abs_path)
            .ok()
            .map(|bytes| blake3::hash(&bytes).to_hex().to_string());
        match (indexed.get(&file.rel_path), disk_hash) {
            (None, _) => pending.push(PendingFile {
                path: file.rel_path,
                reason: "new".to_owned(),
            }),
            (Some(prev), Some(now)) if *prev != now => pending.push(PendingFile {
                path: file.rel_path,
                reason: "modified".to_owned(),
            }),
            _ => {}
        }
    }
    for path in indexed.keys() {
        if !on_disk.contains(path) {
            pending.push(PendingFile {
                path: path.clone(),
                reason: "deleted".to_owned(),
            });
        }
    }

    Ok(IndexStatus {
        files: files as u64,
        symbols: symbols as u64,
        refs: refs as u64,
        schema_version,
        pending,
    })
}

//! Tree-sitter symbol and reference extraction for the supported languages.
//!
//! Each language supplies two queries: a *symbols* query whose captures are
//! named after the [`SymbolKind`] they produce (with a `@name` capture on the
//! identifier), and a *refs* query whose captures (`@call` / `@reference`) mark
//! the textual target of an outgoing edge. Reference edges are attributed to
//! the innermost enclosing symbol at build time, so unattributed top-level
//! references are dropped.

use streaming_iterator::StreamingIterator;
use tree_sitter::{Node, Parser, Query, QueryCursor};

use crate::model::{Lang, RefKind, SymbolKind};

mod queries;

/// A symbol extracted from a single file.
#[derive(Clone, Debug)]
pub(crate) struct ParsedSymbol {
    pub name: String,
    pub kind: SymbolKind,
    pub start_line: u32,
    pub end_line: u32,
    pub signature: Option<String>,
}

/// An outgoing reference, not yet attributed to its enclosing symbol.
#[derive(Clone, Debug)]
pub(crate) struct ParsedRef {
    pub dst_name: String,
    pub kind: RefKind,
    /// 1-based line the reference occurs on, used to find its enclosing symbol.
    pub line: u32,
}

/// Everything extracted from one file.
#[derive(Clone, Debug, Default)]
pub(crate) struct ParsedFile {
    pub symbols: Vec<ParsedSymbol>,
    pub refs: Vec<ParsedRef>,
}

impl Lang {
    fn ts_language(self) -> tree_sitter::Language {
        match self {
            Lang::Rust => tree_sitter_rust::LANGUAGE.into(),
            Lang::Python => tree_sitter_python::LANGUAGE.into(),
            Lang::Go => tree_sitter_go::LANGUAGE.into(),
            Lang::JavaScript => tree_sitter_javascript::LANGUAGE.into(),
            Lang::TypeScript => tree_sitter_typescript::LANGUAGE_TYPESCRIPT.into(),
        }
    }

    fn symbols_query_src(self) -> &'static str {
        match self {
            Lang::Rust => queries::RUST_SYMBOLS,
            Lang::Python => queries::PYTHON_SYMBOLS,
            Lang::Go => queries::GO_SYMBOLS,
            Lang::JavaScript => queries::JAVASCRIPT_SYMBOLS,
            Lang::TypeScript => queries::TYPESCRIPT_SYMBOLS,
        }
    }

    fn refs_query_src(self) -> &'static str {
        match self {
            Lang::Rust => queries::RUST_REFS,
            Lang::Python => queries::PYTHON_REFS,
            Lang::Go => queries::GO_REFS,
            Lang::JavaScript | Lang::TypeScript => queries::JS_TS_REFS,
        }
    }
}

fn kind_from_capture(name: &str) -> Option<SymbolKind> {
    match name {
        "function" => Some(SymbolKind::Function),
        "type" => Some(SymbolKind::Type),
        "interface" => Some(SymbolKind::Interface),
        "enum" => Some(SymbolKind::Enum),
        "constant" => Some(SymbolKind::Constant),
        "module" => Some(SymbolKind::Module),
        _ => None,
    }
}

/// First meaningful line of a definition node — the text up to the first `{` or
/// newline — trimmed and length-capped, used as a human-readable signature.
fn signature_of(node: Node, source: &str) -> Option<String> {
    let text = node.utf8_text(source.as_bytes()).ok()?;
    let end = text.find(['{', '\n']).unwrap_or(text.len());
    let sig = text[..end].trim();
    if sig.is_empty() {
        return None;
    }
    const MAX: usize = 200;
    let sig = if sig.len() > MAX {
        // Truncate on a char boundary.
        let mut cut = MAX;
        while !sig.is_char_boundary(cut) {
            cut -= 1;
        }
        &sig[..cut]
    } else {
        sig
    };
    Some(sig.to_owned())
}

/// Parse one file's source into symbols and unattributed references.
pub(crate) fn parse(lang: Lang, source: &str) -> Result<ParsedFile, crate::SurveyError> {
    let language = lang.ts_language();
    let mut parser = Parser::new();
    parser
        .set_language(&language)
        .map_err(|e| crate::SurveyError::Internal(format!("set_language failed: {e}")))?;
    let tree = parser.parse(source, None).ok_or_else(|| {
        crate::SurveyError::Internal("tree-sitter parse returned None".to_owned())
    })?;
    let root = tree.root_node();

    let symbols = extract_symbols(lang, &language, root, source)?;
    let refs = extract_refs(lang, &language, root, source)?;
    Ok(ParsedFile { symbols, refs })
}

fn extract_symbols(
    lang: Lang,
    language: &tree_sitter::Language,
    root: Node,
    source: &str,
) -> Result<Vec<ParsedSymbol>, crate::SurveyError> {
    let query = Query::new(language, lang.symbols_query_src())
        .map_err(|e| crate::SurveyError::Internal(format!("bad symbols query: {e}")))?;
    let names = query.capture_names();
    let mut cursor = QueryCursor::new();
    let mut out = Vec::new();
    let mut matches = cursor.matches(&query, root, source.as_bytes());
    while let Some(m) = matches.next() {
        let mut def_node: Option<(Node, SymbolKind)> = None;
        let mut name: Option<String> = None;
        for cap in m.captures {
            let cap_name = names[cap.index as usize];
            if cap_name == "name" {
                name = cap
                    .node
                    .utf8_text(source.as_bytes())
                    .ok()
                    .map(str::to_owned);
            } else if let Some(kind) = kind_from_capture(cap_name) {
                def_node = Some((cap.node, kind));
            }
        }
        if let (Some((node, kind)), Some(name)) = (def_node, name) {
            out.push(ParsedSymbol {
                name,
                kind,
                start_line: node.start_position().row as u32 + 1,
                end_line: node.end_position().row as u32 + 1,
                signature: signature_of(node, source),
            });
        }
    }
    Ok(out)
}

fn extract_refs(
    lang: Lang,
    language: &tree_sitter::Language,
    root: Node,
    source: &str,
) -> Result<Vec<ParsedRef>, crate::SurveyError> {
    let query = Query::new(language, lang.refs_query_src())
        .map_err(|e| crate::SurveyError::Internal(format!("bad refs query: {e}")))?;
    let names = query.capture_names();
    let mut cursor = QueryCursor::new();
    let mut out = Vec::new();
    let mut matches = cursor.matches(&query, root, source.as_bytes());
    while let Some(m) = matches.next() {
        for cap in m.captures {
            let kind = match names[cap.index as usize] {
                "call" => RefKind::Call,
                "reference" => RefKind::Reference,
                _ => continue,
            };
            if let Ok(text) = cap.node.utf8_text(source.as_bytes()) {
                out.push(ParsedRef {
                    dst_name: text.to_owned(),
                    kind,
                    line: cap.node.start_position().row as u32 + 1,
                });
            }
        }
    }
    Ok(out)
}

/// Attribute each reference to the innermost symbol whose line span contains
/// it, returning `(src_symbol_index, ref)` pairs. References that fall outside
/// every symbol are dropped.
pub(crate) fn attribute_refs<'a>(
    symbols: &[ParsedSymbol],
    refs: &'a [ParsedRef],
) -> Vec<(usize, &'a ParsedRef)> {
    refs.iter()
        .filter_map(|r| {
            symbols
                .iter()
                .enumerate()
                .filter(|(_, s)| s.start_line <= r.line && r.line <= s.end_line)
                .min_by_key(|(_, s)| s.end_line - s.start_line)
                .map(|(idx, _)| (idx, r))
        })
        .collect()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn rust_extracts_functions_and_calls() {
        let src = "fn helper() {}\nfn caller() {\n    helper();\n}\n";
        let parsed = parse(Lang::Rust, src).unwrap();
        let names: Vec<&str> = parsed.symbols.iter().map(|s| s.name.as_str()).collect();
        assert!(names.contains(&"helper"));
        assert!(names.contains(&"caller"));
        assert!(parsed.refs.iter().any(|r| r.dst_name == "helper"));

        let attributed = attribute_refs(&parsed.symbols, &parsed.refs);
        let caller_idx = parsed
            .symbols
            .iter()
            .position(|s| s.name == "caller")
            .unwrap();
        assert!(attributed
            .iter()
            .any(|(idx, r)| *idx == caller_idx && r.dst_name == "helper"));
    }

    #[test]
    fn python_extracts_classes_and_functions() {
        let src = "class Foo:\n    def method(self):\n        bar()\n\ndef bar():\n    pass\n";
        let parsed = parse(Lang::Python, src).unwrap();
        let names: Vec<&str> = parsed.symbols.iter().map(|s| s.name.as_str()).collect();
        assert!(names.contains(&"Foo"));
        assert!(names.contains(&"method"));
        assert!(names.contains(&"bar"));
        assert!(parsed.refs.iter().any(|r| r.dst_name == "bar"));
    }

    #[test]
    fn go_extracts_funcs_and_types() {
        let src = "package main\ntype T struct{}\nfunc f() {\n\tg()\n}\nfunc g() {}\n";
        let parsed = parse(Lang::Go, src).unwrap();
        let names: Vec<&str> = parsed.symbols.iter().map(|s| s.name.as_str()).collect();
        assert!(names.contains(&"T"));
        assert!(names.contains(&"f"));
        assert!(names.contains(&"g"));
        assert!(parsed.refs.iter().any(|r| r.dst_name == "g"));
    }

    #[test]
    fn typescript_extracts_interface_and_class() {
        let src = "interface I { x: number }\nclass C {\n  m() { fn(); }\n}\nfunction fn() {}\n";
        let parsed = parse(Lang::TypeScript, src).unwrap();
        let names: Vec<&str> = parsed.symbols.iter().map(|s| s.name.as_str()).collect();
        assert!(names.contains(&"I"));
        assert!(names.contains(&"C"));
        assert!(names.contains(&"fn"));
        assert!(parsed.refs.iter().any(|r| r.dst_name == "fn"));
    }

    #[test]
    fn javascript_extracts_arrow_and_calls() {
        let src = "const add = (a, b) => a + b;\nfunction run() {\n  add(1, 2);\n}\n";
        let parsed = parse(Lang::JavaScript, src).unwrap();
        let names: Vec<&str> = parsed.symbols.iter().map(|s| s.name.as_str()).collect();
        assert!(names.contains(&"add"));
        assert!(names.contains(&"run"));
        assert!(parsed.refs.iter().any(|r| r.dst_name == "add"));
    }
}

//! MCP server exposing the survey index to coding agents (DESIGN.md §9.B.8).
//!
//! Four tools (`derrick_survey_search` / `_context` / `_impact` / `_status`)
//! over stdio. Freshness has three layers: (1) a debounced [`crate::watch`]
//! rebuild, (2) a per-response staleness banner emitted only while the index is
//! dirty, and (3) a connect-time incremental build before the first query.

use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::Arc;

use rmcp::handler::server::tool::ToolRouter;
use rmcp::handler::server::wrapper::Parameters;
use rmcp::model::{CallToolResult, Content, ServerCapabilities, ServerInfo};
use rmcp::service::ServiceExt;
use rmcp::transport::stdio;
use rmcp::{tool, tool_handler, tool_router, ErrorData as McpError, ServerHandler};
use schemars::JsonSchema;
use serde::Deserialize;

use crate::model::BuildOptions;
use crate::{Survey, SurveyError};

const DEFAULT_LIMIT: usize = 20;

#[derive(Debug, Deserialize, JsonSchema)]
struct QueryParams {
    /// Search terms (matched against symbol names and signatures).
    query: String,
    /// Maximum number of entry-point hits (default 20).
    #[serde(default)]
    limit: Option<usize>,
}

#[derive(Debug, Deserialize, JsonSchema)]
struct ImpactParams {
    /// Symbol name to resolve.
    symbol: String,
}

/// The MCP server state: a shared [`Survey`] plus the watcher's dirty flag.
#[derive(Clone)]
pub(crate) struct SurveyServer {
    survey: Survey,
    dirty: Arc<AtomicBool>,
    tool_router: ToolRouter<Self>,
}

#[tool_router]
impl SurveyServer {
    fn new(survey: Survey, dirty: Arc<AtomicBool>) -> Self {
        Self {
            survey,
            dirty,
            tool_router: Self::tool_router(),
        }
    }

    #[tool(
        description = "Full-text search over indexed symbol names and signatures. \
        Returns matching symbols with file:line locations."
    )]
    async fn derrick_survey_search(
        &self,
        params: Parameters<QueryParams>,
    ) -> Result<CallToolResult, McpError> {
        let limit = params.0.limit.unwrap_or(DEFAULT_LIMIT);
        let hits = self
            .survey
            .search(&params.0.query, limit)
            .await
            .map_err(internal)?;
        self.respond(&hits).await
    }

    #[tool(
        description = "Resolve a query to entry-point symbols plus the symbols \
        they reference — the one-call answer to an architecture question."
    )]
    async fn derrick_survey_context(
        &self,
        params: Parameters<QueryParams>,
    ) -> Result<CallToolResult, McpError> {
        let limit = params.0.limit.unwrap_or(DEFAULT_LIMIT);
        let context = self
            .survey
            .context(&params.0.query, limit)
            .await
            .map_err(internal)?;
        self.respond(&context).await
    }

    #[tool(description = "Show the direct callers and callees of a symbol — its \
        impact radius before you change it.")]
    async fn derrick_survey_impact(
        &self,
        params: Parameters<ImpactParams>,
    ) -> Result<CallToolResult, McpError> {
        let impact = self
            .survey
            .impact(&params.0.symbol)
            .await
            .map_err(internal)?;
        self.respond(&impact).await
    }

    #[tool(
        description = "Index freshness and size summary, including files that \
        differ from the working tree."
    )]
    async fn derrick_survey_status(&self) -> Result<CallToolResult, McpError> {
        let status = self.survey.status().await.map_err(internal)?;
        self.respond(&status).await
    }

    /// Serialize a result to JSON, prefixing a staleness banner only when the
    /// watcher has flagged the index dirty (so the common path stays cheap).
    async fn respond<T: serde::Serialize>(&self, value: &T) -> Result<CallToolResult, McpError> {
        let mut contents = Vec::new();
        if self.dirty.load(Ordering::Relaxed) {
            if let Ok(status) = self.survey.status().await {
                if !status.pending.is_empty() {
                    let sample: Vec<&str> = status
                        .pending
                        .iter()
                        .take(10)
                        .map(|p| p.path.as_str())
                        .collect();
                    contents.push(Content::text(format!(
                        "STALE: {} file(s) differ from the index (e.g. {}). \
                         A rebuild is in progress; Read these files directly if you need current contents.",
                        status.pending.len(),
                        sample.join(", ")
                    )));
                }
            }
        }
        let json = serde_json::to_string_pretty(value)
            .map_err(|e| McpError::internal_error(e.to_string(), None))?;
        contents.push(Content::text(json));
        Ok(CallToolResult::success(contents))
    }
}

#[tool_handler]
impl ServerHandler for SurveyServer {
    fn get_info(&self) -> ServerInfo {
        ServerInfo {
            instructions: Some(
                "Query derrick's native code-graph index instead of fanning out across \
                 grep/glob/read. Use derrick_survey_search to find symbols, \
                 derrick_survey_context for architecture questions, derrick_survey_impact \
                 before changing a symbol, and derrick_survey_status to check freshness."
                    .to_owned(),
            ),
            capabilities: ServerCapabilities::builder().enable_tools().build(),
            ..Default::default()
        }
    }
}

fn internal(error: SurveyError) -> McpError {
    McpError::internal_error(error.to_string(), None)
}

/// Run the MCP server over stdio until the client disconnects.
///
/// Performs a connect-time incremental build (freshness layer 3), spawns the
/// debounced watcher (layer 1), then serves the four tools.
pub async fn serve_stdio(survey: Survey) -> Result<(), SurveyError> {
    // Layer 3: reconcile the index with the tree before answering anything.
    survey.build(BuildOptions::default()).await?;

    // Layer 1: background watcher keeps the index fresh and flips the dirty flag.
    let dirty = Arc::new(AtomicBool::new(false));
    tokio::spawn(watch_task(survey.clone(), Arc::clone(&dirty)));

    let server = SurveyServer::new(survey, dirty);
    let running = server
        .serve(stdio())
        .await
        .map_err(|e| SurveyError::Internal(format!("mcp serve failed: {e}")))?;
    running
        .waiting()
        .await
        .map_err(SurveyError::Join)
        .map(|_| ())
}

async fn watch_task(survey: Survey, dirty: Arc<AtomicBool>) {
    if let Err(error) = crate::watch::watch_loop(survey, dirty).await {
        tracing::warn!(%error, "survey watcher stopped");
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::{SurveyConfig, SurveyError};
    use rmcp::model::CallToolRequestParam;
    use rmcp::service::ServiceExt;

    async fn temp_survey() -> (tempfile::TempDir, Survey) {
        let tmp = tempfile::tempdir().unwrap();
        let repo = tmp.path();
        std::fs::write(
            repo.join("lib.rs"),
            "pub fn helper() {}\npub fn caller() {\n    helper();\n}\n",
        )
        .unwrap();
        std::fs::create_dir_all(repo.join(".derrick")).unwrap();
        let survey = Survey::open(SurveyConfig {
            db_path: repo.join(".derrick/index.db"),
            repo_root: repo.to_path_buf(),
            reader_pool: SurveyConfig::DEFAULT_READER_POOL,
        })
        .await
        .unwrap();
        survey.build(BuildOptions::default()).await.unwrap();
        (tmp, survey)
    }

    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn mcp_lists_and_calls_tools() -> Result<(), SurveyError> {
        let (_tmp, survey) = temp_survey().await;
        let (server_io, client_io) = tokio::io::duplex(8192);

        let server = SurveyServer::new(survey, Arc::new(AtomicBool::new(false)));
        let server_handle = tokio::spawn(async move {
            let running = server.serve(server_io).await.unwrap();
            let _ = running.waiting().await;
        });

        let client = rmcp::serve_client((), client_io).await.unwrap();

        let tools = client.list_all_tools().await.unwrap();
        let names: Vec<String> = tools.iter().map(|t| t.name.to_string()).collect();
        assert!(names.contains(&"derrick_survey_search".to_owned()));
        assert!(names.contains(&"derrick_survey_context".to_owned()));
        assert!(names.contains(&"derrick_survey_impact".to_owned()));
        assert!(names.contains(&"derrick_survey_status".to_owned()));

        let result = client
            .call_tool(CallToolRequestParam {
                name: "derrick_survey_search".into(),
                arguments: serde_json::json!({ "query": "helper", "limit": 5 })
                    .as_object()
                    .cloned(),
            })
            .await
            .unwrap();
        let body: String = result
            .content
            .iter()
            .filter_map(|c| c.as_text().map(|t| t.text.clone()))
            .collect();
        assert!(
            body.contains("helper"),
            "search result should mention helper: {body}"
        );

        client.cancel().await.unwrap();
        server_handle.abort();
        Ok(())
    }
}

//! The index build pipeline: discover → hash → parse (parallel) → write (one
//! transaction). The whole function is synchronous and is invoked from
//! [`crate::Survey::build`] inside `spawn_blocking`.

use std::collections::HashMap;
use std::fs;
use std::path::Path;
use std::time::UNIX_EPOCH;

use rayon::prelude::*;
use rusqlite::{params, Connection};

use crate::model::{BuildOptions, BuildReport};
use crate::parse::{self, ParsedFile};
use crate::walk::{self, Discovered};
use crate::SurveyError;

/// A discovered file with its content and freshness metadata.
struct FileMeta {
    rel_path: String,
    lang: crate::model::Lang,
    content: String,
    size: i64,
    mtime: i64,
    hash: String,
}

/// Read a file as UTF-8 and compute its content hash and freshness metadata.
/// Returns `None` for files that cannot be read as UTF-8 (binaries, etc.).
fn read_meta(file: &Discovered) -> Option<FileMeta> {
    let content = fs::read_to_string(&file.abs_path).ok()?;
    let meta = fs::metadata(&file.abs_path).ok()?;
    let mtime = meta
        .modified()
        .ok()
        .and_then(|t| t.duration_since(UNIX_EPOCH).ok())
        .map_or(0, |d| d.as_secs() as i64);
    let hash = blake3::hash(content.as_bytes()).to_hex().to_string();
    Some(FileMeta {
        rel_path: file.rel_path.clone(),
        lang: file.lang,
        size: meta.len() as i64,
        mtime,
        hash,
        content,
    })
}

/// Run a full or incremental build against an open writer connection.
pub(crate) fn run(
    connection: &mut Connection,
    repo_root: &Path,
    options: BuildOptions,
) -> Result<BuildReport, SurveyError> {
    let discovered = walk::discover(repo_root);

    // Phase 1: read + hash every discovered file in parallel.
    let metas: Vec<FileMeta> = discovered.par_iter().filter_map(read_meta).collect();

    // Existing index state: path -> content_hash.
    let existing = load_existing_hashes(connection)?;

    // Phase 2: split into changed (reparse) vs unchanged.
    let (changed, unchanged): (Vec<&FileMeta>, Vec<&FileMeta>) = metas.iter().partition(|m| {
        options.full || existing.get(&m.rel_path).is_none_or(|prev| prev != &m.hash)
    });

    // Phase 3: parse changed files in parallel.
    let parsed: Vec<(&FileMeta, ParsedFile)> = changed
        .par_iter()
        .map(|m| parse::parse(m.lang, &m.content).map(|p| (*m, p)))
        .collect::<Result<_, _>>()?;

    // Phase 4: one transaction for all writes.
    let on_disk: std::collections::HashSet<&str> =
        metas.iter().map(|m| m.rel_path.as_str()).collect();
    let mut files_removed = 0u64;

    let tx = connection.transaction()?;
    {
        // Remove index entries for files no longer on disk.
        for path in existing.keys() {
            if !on_disk.contains(path.as_str()) {
                tx.execute("DELETE FROM files WHERE path = ?1", params![path])?;
                files_removed += 1;
            }
        }

        for (meta, file) in &parsed {
            write_file(&tx, meta, file)?;
        }

        // Resolve reference targets to symbol ids by name (best-effort; ambiguous
        // names resolve to an arbitrary match). Unresolved refs keep dst_name only.
        tx.execute(
            "UPDATE refs SET dst_symbol_id = (
                 SELECT s.id FROM symbols s WHERE s.name = refs.dst_name LIMIT 1
             )",
            [],
        )?;

        // External-content FTS5 has no triggers; rebuild it from the symbols
        // table wholesale now that all symbol writes are done.
        tx.execute("INSERT INTO symbols_fts(symbols_fts) VALUES('rebuild')", [])?;
    }
    tx.commit()?;

    let (symbols, refs) = counts(connection)?;
    Ok(BuildReport {
        files_indexed: parsed.len() as u64,
        files_removed,
        files_unchanged: unchanged.len() as u64,
        symbols,
        refs,
    })
}

/// Delete and re-insert one file's symbols and reference edges.
fn write_file(tx: &Connection, meta: &FileMeta, file: &ParsedFile) -> Result<(), SurveyError> {
    // Deleting the file row cascades to its symbols (and their outgoing refs).
    tx.execute("DELETE FROM files WHERE path = ?1", params![meta.rel_path])?;
    tx.execute(
        "INSERT INTO files (path, lang, size, mtime, content_hash)
         VALUES (?1, ?2, ?3, ?4, ?5)",
        params![
            meta.rel_path,
            meta.lang.as_str(),
            meta.size,
            meta.mtime,
            meta.hash
        ],
    )?;
    let file_id = tx.last_insert_rowid();

    // Insert symbols, recording their row ids by source order.
    let mut symbol_ids = Vec::with_capacity(file.symbols.len());
    for sym in &file.symbols {
        tx.execute(
            "INSERT INTO symbols (file_id, name, kind, start_line, end_line, signature)
             VALUES (?1, ?2, ?3, ?4, ?5, ?6)",
            params![
                file_id,
                sym.name,
                sym.kind.as_str(),
                sym.start_line,
                sym.end_line,
                sym.signature
            ],
        )?;
        symbol_ids.push(tx.last_insert_rowid());
    }

    // Attribute each reference to its enclosing symbol and insert the edge.
    for (src_idx, r) in parse::attribute_refs(&file.symbols, &file.refs) {
        tx.execute(
            "INSERT INTO refs (src_symbol_id, dst_symbol_id, dst_name, kind)
             VALUES (?1, NULL, ?2, ?3)",
            params![symbol_ids[src_idx], r.dst_name, r.kind.as_str()],
        )?;
    }
    Ok(())
}

fn load_existing_hashes(connection: &Connection) -> Result<HashMap<String, String>, SurveyError> {
    let mut stmt = connection.prepare("SELECT path, content_hash FROM files")?;
    let rows = stmt.query_map([], |row| {
        Ok((row.get::<_, String>(0)?, row.get::<_, String>(1)?))
    })?;
    let mut map = HashMap::new();
    for row in rows {
        let (path, hash) = row?;
        map.insert(path, hash);
    }
    Ok(map)
}

fn counts(connection: &Connection) -> Result<(u64, u64), SurveyError> {
    let symbols: i64 = connection.query_row("SELECT COUNT(*) FROM symbols", [], |r| r.get(0))?;
    let refs: i64 = connection.query_row("SELECT COUNT(*) FROM refs", [], |r| r.get(0))?;
    Ok((symbols as u64, refs as u64))
}

