use std::collections::HashMap;
use std::sync::LazyLock;

use streaming_iterator::StreamingIterator;
use tree_sitter::{Node, Parser, Query, QueryCursor};

use crate::model::{Lang, RefKind, SymbolKind};

mod queries;

/// Per-language tree-sitter language handle plus its pre-compiled symbol and
/// reference queries. Compiling a [`Query`] is expensive, so we do it once.
struct CompiledQueries {
    language: tree_sitter::Language,
    symbols: Query,
    refs: Query,
}

/// All five languages' queries, compiled once on first parse. The built-in
/// query sources are constants, so a compile failure is a programmer error.
static QUERIES: LazyLock<HashMap<Lang, CompiledQueries>> = LazyLock::new(|| {
    [
        Lang::Rust,
        Lang::Python,
        Lang::Go,
        Lang::JavaScript,
        Lang::TypeScript,
    ]
    .into_iter()
    .map(|lang| {
        let language = lang.ts_language();
        let symbols = Query::new(&language, lang.symbols_query_src())
            .expect("built-in symbols query must compile");
        let refs = Query::new(&language, lang.refs_query_src())
            .expect("built-in refs query must compile");
        (
            lang,
            CompiledQueries {
                language,
                symbols,
                refs,
            },
        )
    })
    .collect()
