) {
    let existing = hooks.entry(stage).or_insert_with(|| json!([]));
    if !existing.is_array() {
        blockers.push(format!(".claude/settings.json {stage} must be an array"));
        return;
    }
    let Some(array) = existing.as_array_mut() else {
        blockers.push(format!(".claude/settings.json {stage} must be an array"));
        return;

