 "# /add-feature\n\nRun `derrick run add-feature --prompt \"$ARGUMENTS\"`.\n"
 }
 "derrick-status.md" => "# /derrick-status\n\nRun `derrick status`.\n",
 "derrick-doctor.md" => "# /derrick-doctor\n\nRun `derrick doctor`.\n",
 "derrick-resume.md" => {
