 settings.content
 );
 let allow = value["permissions"]["allow"]
.as_array()
.unwrap_or_else(|| panic!("missing permissions.allow"));
 assert!(allow
.iter()
.any(|v| v.as_str() == Some("mcp__derrick-survey__derrick_survey_search")));

 options.site_prefix = "TOOLONG".to_owned();
