1	//! Tree-sitter symbol and reference extraction for the supported languages.
2	//!
3	//! Each language supplies two queries: a *symbols* query whose captures are
4	//! named after the [`SymbolKind`] they produce (with a `@name` capture on the
5	//! identifier), and a *refs* query whose captures (`@call` / `@reference`) mark
6	//! the textual target of an outgoing edge. Reference edges are attributed to
7	//! the innermost enclosing symbol at build time, so unattributed top-level
8	//! references are dropped.
9	
10	use std::collections::HashMap;
11	use std::sync::LazyLock;
12	
13	use streaming_iterator::StreamingIterator;
14	use tree_sitter::{Node, Parser, Query, QueryCursor};
15	
16	use crate::model::{Lang, RefKind, SymbolKind};
17	
18	mod queries;
19	
20	/// Per-language tree-sitter language handle plus its pre-compiled symbol and
21	/// reference queries. Compiling a [`Query`] is expensive, so we do it once.
22	struct CompiledQueries {
23	    language: tree_sitter::Language,
24	    symbols: Query,
25	    refs: Query,
26	}
27	
28	/// All five languages' queries, compiled once on first parse. The built-in
29	/// query sources are constants, so a compile failure is a programmer error.
30	static QUERIES: LazyLock<HashMap<Lang, CompiledQueries>> = LazyLock::new(|| {
31	    [
32	        Lang::Rust,
33	        Lang::Python,
34	        Lang::Go,
35	        Lang::JavaScript,
36	        Lang::TypeScript,
37	    ]
38	    .into_iter()
39	    .map(|lang| {
40	        let language = lang.ts_language();
41	        let symbols = Query::new(&language, lang.symbols_query_src())
42	            .expect("built-in symbols query must compile");
43	        let refs =
44	            Query::new(&language, lang.refs_query_src()).expect("built-in refs query must compile");
45	        (
46	            lang,
47	            CompiledQueries {
48	                language,
49	                symbols,
50	                refs,
51	            },
52	        )
53	    })
54	    .collect()
55	});
56	
57	/// A symbol extracted from a single file.
58	#[derive(Clone, Debug)]
59	pub(crate) struct ParsedSymbol {
60	    pub name: String,
61	    pub kind: SymbolKind,
62	    pub start_line: u32,
63	    pub end_line: u32,
64	    pub signature: Option<String>,
65	}
66	
67	/// An outgoing reference, not yet attributed to its enclosing symbol.
68	#[derive(Clone, Debug)]
69	pub(crate) struct ParsedRef {
70	    pub dst_name: String,
71	    pub kind: RefKind,
72	    /// 1-based line the reference occurs on, used to find its enclosing symbol.
73	    pub line: u32,
74	}
75	
76	/// Everything extracted from one file.
77	#[derive(Clone, Debug, Default)]
78	pub(crate) struct ParsedFile {
79	    pub symbols: Vec<ParsedSymbol>,
80	    pub refs: Vec<ParsedRef>,
81	}
82	
83	impl Lang {
84	    fn ts_language(self) -> tree_sitter::Language {
85	        match self {
86	            Lang::Rust => tree_sitter_rust::LANGUAGE.into(),
87	            Lang::Python => tree_sitter_python::LANGUAGE.into(),
88	            Lang::Go => tree_sitter_go::LANGUAGE.into(),
89	            Lang::JavaScript => tree_sitter_javascript::LANGUAGE.into(),
90	            Lang::TypeScript => tree_sitter_typescript::LANGUAGE_TYPESCRIPT.into(),
91	        }
92	    }
93	
94	    fn symbols_query_src(self) -> &'static str {
95	        match self {
96	            Lang::Rust => queries::RUST_SYMBOLS,
97	            Lang::Python => queries::PYTHON_SYMBOLS,
98	            Lang::Go => queries::GO_SYMBOLS,
99	            Lang::JavaScript => queries::JAVASCRIPT_SYMBOLS,
100	            Lang::TypeScript => queries::TYPESCRIPT_SYMBOLS,
101	        }
102	    }
103	
104	    fn refs_query_src(self) -> &'static str {
105	        match self {
106	            Lang::Rust => queries::RUST_REFS,
107	            Lang::Python => queries::PYTHON_REFS,
108	            Lang::Go => queries::GO_REFS,
109	            Lang::JavaScript | Lang::TypeScript => queries::JS_TS_REFS,
110	        }
111	    }
112	}
113	
114	fn kind_from_capture(name: &str) -> Option<SymbolKind> {
115	    match name {
116	        "function" => Some(SymbolKind::Function),
117	        "type" => Some(SymbolKind::Type),
118	        "interface" => Some(SymbolKind::Interface),
119	        "enum" => Some(SymbolKind::Enum),
120	        "constant" => Some(SymbolKind::Constant),
121	        "module" => Some(SymbolKind::Module),
122	        _ => None,
123	    }
124	}
125	
126	/// First meaningful line of a definition node — the text up to the first `{` or
127	/// newline — trimmed and length-capped, used as a human-readable signature.
128	fn signature_of(node: Node, source: &str) -> Option<String> {
129	    let text = node.utf8_text(source.as_bytes()).ok()?;
130	    let end = text.find(['{', '\n']).unwrap_or(text.len());
131	    let sig = text[..end].trim();
132	    if sig.is_empty() {
133	        return None;
134	    }
135	    const MAX: usize = 200;
136	    let sig = if sig.len() > MAX {
137	        // Truncate on a char boundary.
138	        let mut cut = MAX;
139	        while !sig.is_char_boundary(cut) {
140	            cut -= 1;
141	        }
142	        &sig[..cut]
143	    } else {
144	        sig
145	    };
146	    Some(sig.to_owned())
147	}
148	
149	/// Parse one file's source into symbols and unattributed references.
150	pub(crate) fn parse(lang: Lang, source: &str) -> Result<ParsedFile, crate::SurveyError> {
151	    let queries = &QUERIES[&lang];
152	    let mut parser = Parser::new();
153	    parser
154	        .set_language(&queries.language)
155	        .map_err(|e| crate::SurveyError::Internal(format!("set_language failed: {e}")))?;
156	    let tree = parser.parse(source, None).ok_or_else(|| {
157	        crate::SurveyError::Internal("tree-sitter parse returned None".to_owned())
158	    })?;
159	    let root = tree.root_node();
160	
161	    let symbols = extract_symbols(&queries.symbols, root, source);
162	    let refs = extract_refs(&queries.refs, root, source);
163	    Ok(ParsedFile { symbols, refs })
164	}
165	
166	fn extract_symbols(query: &Query, root: Node, source: &str) -> Vec<ParsedSymbol> {
167	    let names = query.capture_names();
168	    let mut cursor = QueryCursor::new();
169	    let mut out = Vec::new();
170	    let mut matches = cursor.matches(query, root, source.as_bytes());
171	    while let Some(m) = matches.next() {
172	        let mut def_node: Option<(Node, SymbolKind)> = None;
173	        let mut name: Option<String> = None;
174	        for cap in m.captures {
175	            let cap_name = names[cap.index as usize];
176	            if cap_name == "name" {
177	                name = cap
178	                    .node
179	                    .utf8_text(source.as_bytes())
180	                    .ok()
181	                    .map(str::to_owned);
182	            } else if let Some(kind) = kind_from_capture(cap_name) {
183	                def_node = Some((cap.node, kind));
184	            }
185	        }
186	        if let (Some((node, kind)), Some(name)) = (def_node, name) {
187	            out.push(ParsedSymbol {
188	                name,
189	                kind,
190	                start_line: node.start_position().row as u32 + 1,
191	                end_line: node.end_position().row as u32 + 1,
192	                signature: signature_of(node, source),
193	            });
194	        }
195	    }
196	    out
197	}
198	
199	fn extract_refs(query: &Query, root: Node, source: &str) -> Vec<ParsedRef> {
200	    let names = query.capture_names();
201	    let mut cursor = QueryCursor::new();
202	    let mut out = Vec::new();
203	    let mut matches = cursor.matches(query, root, source.as_bytes());
204	    while let Some(m) = matches.next() {
205	        for cap in m.captures {
206	            let kind = match names[cap.index as usize] {
207	                "call" => RefKind::Call,
208	                "reference" => RefKind::Reference,
209	                _ => continue,
210	            };
211	            if let Ok(text) = cap.node.utf8_text(source.as_bytes()) {
212	                out.push(ParsedRef {
213	                    dst_name: text.to_owned(),
214	                    kind,
215	                    line: cap.node.start_position().row as u32 + 1,

