        if let Some(id) = msg.id {
            if !seen.insert(id) {
                continue;
            }
        }

        let Some(u) = msg.usage else { continue };

        usage.input_tokens = usage
            .input_tokens
            .saturating_add(u.input_tokens.unwrap_or(0));
